+        let mut allocator = FRAME_ALLOCATOR.exclusive_access();
+        allocator.dealloc(ppn);
+        allocator.page_counts()
+    };
+    nodefusion_trace_page(NFT_KFREE, PhysAddr::from(ppn).0, free_pages, used_pages);
 }

